      formulas: [{ eq: 'v(A rel C) = v(A rel B) + v(B rel C)', id: 'relvel', vars: [['v(A rel B)', 'velocity of A measured by B', 'm/s']], when: 'Any speeds much less than light (Galilean relativity).' }],
